function invalid():never{throw new TypeError('NATIVE_SOURCE_V3_CONTRACT_INVALID')}
function record(v:unknown,keys:readonly string[]):Record<string,unknown>{if(v===null||typeof v!=='object'||Object.getPrototypeOf(v)!==Object.prototype)invalid();const ds=Object.getOwnPropertyDescriptors(v),own=Reflect.ownKeys(v);if(own.length!==keys.length||own.some(k=>typeof k!=='string'||!keys.includes(k)||!Object.hasOwn(ds[k]??{},'value')))invalid();return v as Record<string,unknown>}
